#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.."&&pwd)";VERSION="$(tr -d '\r\n'<"$ROOT/VERSION")";DIST="$ROOT/dist";WORK="$ROOT/build/.work";rm -rf "$DIST" "$WORK";mkdir -p "$DIST" "$WORK/component" "$WORK/package";cp -R "$ROOT/component/." "$WORK/component/";(cd "$WORK/component"&&find . -type f -print0|sort -z|xargs -0 zip -X -q "$DIST/com_xdecaroinventory_${VERSION}.zip");cp "$ROOT/package/pkg_xdecaroinventory.xml" "$WORK/package/pkg_xdecaroinventory.xml";cp "$ROOT/package/script.php" "$WORK/package/script.php";cp "$DIST/com_xdecaroinventory_${VERSION}.zip" "$WORK/package/com_xdecaroinventory.zip";(cd "$WORK/package"&&find . -type f -print0|sort -z|xargs -0 zip -X -q "$DIST/pkg_xdecaroinventory_${VERSION}.zip");(cd "$DIST"&&sha256sum "com_xdecaroinventory_${VERSION}.zip" "pkg_xdecaroinventory_${VERSION}.zip">SHA256SUMS.txt)
